const items = $input.all();

let moved = [];
try {
  moved = $('ย้ายไป 2-Processing').all();
} catch (e) {
  moved = [];
}

const out = [];

for (let idx = 0; idx < items.length; idx++) {
  const j = items[idx].json || {};

  // --------------------------------------------------
  // 1. อ่าน metadata ของไฟล์ต้นฉบับ
  // --------------------------------------------------
  let fileId = null;
  let fileName = null;
  let mimeType = null;

  try {
    const mv = moved[idx];

    if (mv && mv.json) {
      fileId = mv.json.id || null;
      fileName = mv.json.name || null;
      mimeType = mv.json.mimeType || null;
    }
  } catch (e) {}

  const extension = fileName && fileName.includes('.')
    ? fileName.split('.').pop().toLowerCase()
    : null;

  const fileMeta = {
    id: fileId,
    name: fileName,
    extension,
    mime_type: mimeType,
    drive_link: fileId
      ? `https://drive.google.com/file/d/${fileId}/view`
      : null
  };

  // --------------------------------------------------
  // 2. ดึงข้อความดิบจาก Gemini
  //    เก็บ raw ก่อน clean / JSON.parse
  // --------------------------------------------------
  let raw = '';

  try {
    if (
      j.content &&
      j.content.parts &&
      j.content.parts[0] &&
      typeof j.content.parts[0].text === 'string'
    ) {
      raw = j.content.parts[0].text;

    } else if (typeof j.text === 'string') {
      raw = j.text;

    } else if (
      j.candidates &&
      j.candidates[0] &&
      j.candidates[0].content &&
      j.candidates[0].content.parts &&
      j.candidates[0].content.parts[0] &&
      typeof j.candidates[0].content.parts[0].text === 'string'
    ) {
      raw = j.candidates[0].content.parts[0].text;

    } else {
      raw = JSON.stringify(j);
    }

    // --------------------------------------------------
    // 3. Clean เฉพาะสำเนาที่จะนำไป JSON.parse
    //    raw ด้านบนยังคงข้อความเดิม 100%
    // --------------------------------------------------
    let clean = String(raw || '').trim();

    const fenced = clean.match(
      /```(?:json)?\s*([\s\S]*?)\s*```/i
    );

    if (fenced && fenced[1]) {
      clean = fenced[1].trim();
    }

    clean = clean
      .replace(/^```(?:json)?/i, '')
      .replace(/```$/i, '')
      .trim();

    const parsed = JSON.parse(clean);

    // --------------------------------------------------
    // 4. คืนค่าแบบ backward-compatible
    //    downstream เดิมยังใช้ machine_raw, rows ฯลฯ ได้
    // --------------------------------------------------
    out.push({
      json: {
        ...parsed,

        _fileId: fileId,
        _fileName: fileName,

        _file: fileMeta,
        _ocr_raw_text: raw,
        _ocr_error: null
      }
    });

  } catch (e) {
    // --------------------------------------------------
    // OCR ตอบมาแต่ parse JSON ไม่สำเร็จ
    // --------------------------------------------------
    out.push({
      json: {
        _ocr_error: e.message,
        _ocr_raw_text: raw,

        _fileId: fileId,
        _fileName: fileName,
        _file: fileMeta
      }
    });
  }
}

return out;

// MOCK OCR — ข้อมูลฟอร์มจริง (ภาพ 0001) กำหนดเครื่อง = PF8/5 เพื่อทดสอบ downstream
return [{ json: {
  machine_raw: "PF8/5",
  product: "ธีรเดช กาญจนสิทธิ์ 12",
  date: { day: 17, month: 6, year_be: 69 },
  rows: [
    { no:1, stop:"09:00", start:"09:15", duration_text:"15", cause:"T.E Bottle clamp op CAV2-12",      remedy:null, operator:"ธีรเดช",      technician:"Wai" },
    { no:2, stop:"10:20", start:"10:25", duration_text:"5",  cause:"TE. INVERSE UNIT FWCSO 104 / AV1",  remedy:null, operator:"\"",          technician:"\"" },
    { no:3, stop:"12:35", start:"12:40", duration_text:"5",  cause:"S.E. Receipt op/วอ (sq91/92)",      remedy:null, operator:"ภูธร+ธีรเดช", technician:"\"" },
    { no:4, stop:"14:10", start:"14:20", duration_text:"10", cause:"S.E Receipt op/วอ. (sq 91/92)",     remedy:null, operator:"ธร + สุวิมล", technician:"แว" },
    { no:5, stop:"14:30", start:"14:35", duration_text:"5",  cause:"ช่างหยุดเครื่อง เป่ารั่ว M1,2,3,4", remedy:null, operator:"\"",          technician:"\"" },
    { no:6, stop:"15:00", start:"15:05", duration_text:"5",  cause:"ช่างหยุดเครื่อง เป่ารั่ว M1,2,3,4", remedy:null, operator:"\"",          technician:"\"" },
    { no:7, stop:"18:00", start:"18:10", duration_text:"10", cause:"ช่างหยุดเครื่อง เป่ารั่ว M1,2,3,4", remedy:null, operator:"\"",          technician:"\"" },
    { no:8, stop:"18:40", start:null,    duration_text:null, cause:"ช่างหยุดเครื่องย้ายอะไหล่ไป PF8/3", remedy:null, operator:null,        technician:null }
  ],
  round_summary_note: null
} }];

// map เครื่อง->ชื่อแท็บจริง (มี /), วันที่ "ใช้จากชื่อไฟล์เป็นหลัก" (fallback OCR), แบ่งรอบตามเวลาปิด(รายแถว), ditto-fill, ฝัง rate
// อัปเดต: วันที่ยึดจากชื่อไฟล์ YYYYMMDD ก่อนเสมอ (แก้ปัญหา OCR อ่านวันที่ผิด/อนาคต) + เก็บแถว "มีแต่เวลาปิด/มีแต่เวลาเปิด"
const o = $input.first().json;
if (o._ocr_error) return [{ json: o }];
const MACHINE_MAP = {
  "PF8/3":"PF8/3","PF8/5":"PF8/5","PF8/6":"PF8/6","PF8/7":"PF8/7","PF8/8":"PF8/8",
  "250/3":"ASB250/3","ASB250/3":"ASB250/3","ASB250":"ASB250/3",
  "TE":"TE","TRUE EASY":"TE","TURE EASY":"TE","KM175":"KM175","NB40":"NB40"
};
const RATE = {
  "PF8/3":[2571,42,2.38],"PF8/5":[2571,42,2.38],"PF8/6":[2571,42,2.38],"PF8/7":[2300,39,2.38],
  "PF8/8":[2571,42,2.38],"ASB250/3":[2300,39,2.38],"TE":[2571,42,2.38],"KM175":[2300,39,4.5],"NB40":[1309,22,2.38]
};
const DICT_FOR = {
  "PF8/3":"SD-DEM-056 | PF8/3","PF8/5":"SD-DEM-056 | PF8/3",
  "PF8/6":"SD-DEM-056 | PF8/6","PF8/7":"SD-DEM-056 | PF8/6","ASB250/3":"SD-DEM-056 | PF8/6",
  "PF8/8":"SD-DEM-056 | PF8/8","TE":"SD-DEM-056 | PF8/8"
};
function mapMachine(raw){
  const ex=String(raw||"").toUpperCase().trim();
  if (MACHINE_MAP[ex]) return MACHINE_MAP[ex];
  const k=ex.replace(/\s+/g,"");
  for (const key in MACHINE_MAP){ if (key.toUpperCase().replace(/\s+/g,"")===k) return MACHINE_MAP[key]; }
  return null;
}
function be2ce(y){ y=parseInt(y,10); if(y<100) y=2500+y; return y-543; }
function toMin(t){ if(!t) return null; const m=String(t).match(/(\d{1,2}):(\d{2})/); return m?(+m[1])*60+(+m[2]):null; }
function isDitto(v){ v=String(v||"").trim(); return ['"','”','„','“',"''","ๆ","/","//"].includes(v); }
// รอบตามเวลา: รอบ1 08:00-19:59, รอบ2 20:00-07:59
function roundOf(min){ return (min>=8*60 && min<=19*60+59) ? 1 : 2; }
const sheet=mapMachine(o.machine_raw);
const d=o.date||{};
// ---- วันที่: ใช้จากชื่อไฟล์เป็นหลัก (YYYYMMDD) ถ้าชื่อไฟล์ไม่มีวันที่ค่อย fallback ไปใช้ค่าจาก OCR ----
const _fnDate=String(o._fileName||"").match(/(?:^|[^0-9])(20\d{2})(\d{2})(\d{2})(?:[^0-9]|$)/);
let yy, mm, dd, _dateSrc;
if(_fnDate){ yy=parseInt(_fnDate[1],10); mm=_fnDate[2]; dd=_fnDate[3]; _dateSrc="filename"; }
else { yy=be2ce(d.year_be); mm=String(d.month).padStart(2,"0"); dd=String(d.day).padStart(2,"0"); _dateSrc="ocr"; }
const date_iso=yy+"-"+mm+"-"+dd, date_disp=dd+"-"+mm+"-"+yy;
// ---- ตรวจความสมเหตุผล (day 1-31, month 1-12); future-check เฉพาะตอน fallback OCR (ชื่อไฟล์เชื่อถือได้กว่า) ----
const _dayN=parseInt(dd,10), _monN=parseInt(mm,10);
let _today; try { _today=$now.toFormat('yyyy-LL-dd'); } catch(e){ const _t=new Date(); _today=_t.getFullYear()+"-"+String(_t.getMonth()+1).padStart(2,"0")+"-"+String(_t.getDate()).padStart(2,"0"); }
let _dateErr=null;
if(!(_dayN>=1&&_dayN<=31)) _dateErr="วันที่ไม่สมเหตุผล (day="+dd+") ต้องอยู่ 1-31";
else if(!(_monN>=1&&_monN<=12)) _dateErr="เดือนไม่สมเหตุผล (month="+mm+") ต้องอยู่ 1-12";
else if(_dateSrc==="ocr" && date_iso>_today) _dateErr="วันที่ OCR ("+date_disp+") เกินวันปัจจุบัน ("+_today+") และชื่อไฟล์ไม่มีวันที่ให้ใช้แทน";
if(_dateErr) return [{ json:{ _error:_dateErr, dictSheet:"SD-DEM-056 | PF8/3", ocr:o, _fileId:o._fileId||null, _fileName:o._fileName||null } }];
if(!sheet) return [{ json:{ _error:"ไม่รู้จักเครื่อง: "+o.machine_raw, dictSheet:"SD-DEM-056 | PF8/3", ocr:o, _fileId:o._fileId||null, _fileName:o._fileName||null } }];
const rr=RATE[sheet];
const dictSheet=DICT_FOR[sheet]||"SD-DEM-056 | PF8/3";
const hasDict=!!DICT_FOR[sheet];
// รอบสำรองระดับฟอร์ม (ใช้กับแถวที่ไม่มีเวลาเลย): เวลาปิดของแถวแรกที่มี ไม่มีก็ใช้เวลาเปิด
let _ft=null;
for(const r of (o.rows||[])){ const t=toMin(r.stop) ?? toMin(r.start); if(t!=null){ _ft=t; break; } }
const _formRound = _ft!=null ? roundOf(_ft) : 1;
let lastT=null,lastOp=null;
function hasTime(t){ return !!(t && String(t).trim() && /\d{1,2}:\d{2}/.test(String(t))); }
let rows=(o.rows||[]).map(r=>{
  let te=String(r.technician||"").trim(); if(isDitto(te)) te=lastT; else if(te) lastT=te;
  let op=String(r.operator||"").trim(); if(isDitto(op)) op=lastOp; else if(op) lastOp=op;
  const causeTxt=String(r.cause||"").trim();
  const hasStop=hasTime(r.stop), hasStart=hasTime(r.start);
  if(!hasStop && !hasStart && !causeTxt) return null;   // แถวว่างจริง -> ข้าม
  let stopVal, startVal;
  if(hasStop && hasStart){ stopVal=r.stop; startVal=r.start; }
  else if(hasStop){ stopVal=r.stop; startVal="-"; }     // มีแต่เวลาปิด -> เปิด "-" (ระยะเวลา=0)
  else if(hasStart){ stopVal="-"; startVal=r.start; }   // มีแต่เวลาเปิด -> ปิด "-" (ระยะเวลา=0)
  else { stopVal=null; startVal=null; }                 // ไม่มีเวลาแต่มีสาเหตุ(โน้ต) -> ระยะเวลา=0
  const _rt = toMin(r.stop) ?? toMin(r.start);
  const _round = (_rt!=null) ? roundOf(_rt) : _formRound;
  return { stop:stopVal, start:startVal, cause:causeTxt, technician:te||null, operator:op||null, round:_round };
}).filter(Boolean);
// ---- เคสตารางว่าง "เครื่องไม่หยุด": ไม่มีแถวข้อมูลเลย แต่มีเครื่อง+วันที่ -> ใส่แถว "เครื่องไม่หยุด" 1 แถว (ระยะเวลา 0) ----
// (เดิมจะถูกข้ามที่ 'สร้างค่าเขียน' ทำให้ไฟล์ค้างที่ 2-Processing) ตอนนี้เขียนตาม convention จริง (ดูตัวอย่าง PF8/8 แถว 67)
if (rows.length === 0) {
  let anyName=null;   // ดึงชื่อช่าง/ผู้ควบคุมจาก OCR ถ้ามี (แม้อยู่ในแถวที่ปกติจะถูกกรองทิ้ง)
  for (const r of (o.rows||[])){ const t=String(r.technician||"").trim(), op=String(r.operator||"").trim();
    if (t && !isDitto(t)){ anyName=t; break; } if (op && !isDitto(op)){ anyName=op; break; } }
  rows = [{ stop:"00:00", start:"00:00", cause:"เครื่องไม่หยุด", technician:anyName, operator:null, round:1 }];
}
// ---- เลือก spreadsheet ตามเดือนจากชื่อไฟล์ + เตรียมข้อมูลสร้างใหม่ถ้าไม่มี ----
const _TH={1:"มกราคม",2:"กุมภาพันธ์",3:"มีนาคม",4:"เมษายน",5:"พฤษภาคม",6:"มิถุนายน",7:"กรกฎาคม",8:"สิงหาคม",9:"กันยายน",10:"ตุลาคม",11:"พฤศจิกายน",12:"ธันวาคม"};
let _SMAP={}; try { _SMAP=JSON.parse($('ตั้งค่า Spreadsheet1').first().json.sheetMapJson||"{}"); } catch(e){}
const _fnm=_fnDate;   // ใช้ผลลัพธ์ regex เดียวกับด้านบน (วันที่จากชื่อไฟล์)
const _ym=_fnm?(_fnm[1]+"-"+_fnm[2]):null;
const _monthTitle=_fnm?("รายงานการหยุดเครื่องจักร (Machine Breakdown) เดือน "+_fnm[2]+" | "+(_TH[parseInt(_fnm[2],10)]||"")+" "+_fnm[1]):null;
let _SSID=_ym?(_SMAP[_ym]||null):($('ตั้งค่า Spreadsheet1').first().json.defaultSheetId||null);
const _need_resolve=!!(_ym && !_SSID);
const _nmNoExt=String(o._fileName||"").replace(/\.[^.]+$/,"");
const _pm=_nmNoExt.match(/\s*#(\d+)\s*$/);
const _part_no=_pm?parseInt(_pm[1],10):null;
const _is_multipart=_part_no!==null;
const _base_key=_nmNoExt.replace(/\s*#\d+\s*$/,"");
return [{ json:{ machine_raw:o.machine_raw, sheet, hasDict, dictSheet, date_iso, date_disp, round:_formRound,
  spreadsheetId:_SSID, _ym:_ym, _monthTitle:_monthTitle, _need_resolve:_need_resolve,
  rate:{h:rr[0],m:rr[1],n:rr[2]}, round_summary_note:o.round_summary_note||null, rows,
  _base_key:_base_key, _part_no:_part_no, _is_multipart:_is_multipart,
  _fileId:o._fileId||null, _fileName:o._fileName||null } }];

// อ่านจาก $json (Merge รวม prep + dict valueRanges) — ไม่อ้างชื่อ node
const prep = $json;
if (prep._error || prep._ocr_error) return [{ json: prep }];
let dict=[];
try { const vr=prep.valueRanges; const vals=(vr&&vr[0]&&vr[0].values)?vr[0].values:[]; dict=vals.filter(r=>r&&r[0]); } catch(e){}
function norm(s){ return String(s==null?"":s).toUpperCase().replace(/O/g,"0").replace(/[^A-Z0-9]/g,""); }
function roTotal(a,b){
  let total=0; const stack=[[0,a.length,0,b.length]];
  while(stack.length){
    const s=stack.pop(); const a0=s[0],a1=s[1],b0=s[2],b1=s[3];
    let bi=a0,bj=b0,bk=0,j2={};
    for(let i=a0;i<a1;i++){ const nj={};
      for(let j=b0;j<b1;j++){ if(a[i]===b[j]){ const k=(j2[j-1]||0)+1; nj[j]=k; if(k>bk){bk=k;bi=i-k+1;bj=j-k+1;} } }
      j2=nj;
    }
    if(bk>0){ total+=bk; stack.push([a0,bi,b0,bj]); stack.push([bi+bk,a1,bj+bk,b1]); }
  }
  return total;
}
function ratio(a,b){ a=norm(a); b=norm(b); if(!a&&!b)return 1; if(!a||!b)return 0; return 2*roTotal(a,b)/(a.length+b.length); }
function matchCause(raw){
  // FIX: ข้อความไทยล้วน (normalize แล้วว่าง) -> เก็บดิบ ไม่ fuzzy (กันไปแมตช์ entry ไทยตัวแรกผิด ๆ เช่น "เครื่องไม่หยุด")
  if(norm(raw)===""){ return { code:String(raw||"").trim(), thai:"", score:0, matched:false }; }
  let best=0,bc=null,bt=null;
  for(const row of dict){ const r=ratio(raw,row[0]); if(r>best){best=r;bc=row[0];bt=row[1];} }
  if(best>=0.6) return { code:bc, thai:(bt||""), score:+best.toFixed(2), matched:true };
  return { code:raw, thai:"", score:+best.toFixed(2), matched:false };
}
function toMin(t){ if(!t) return null; const m=String(t).match(/(\d{1,2}):(\d{2})/); return m?(+m[1])*60+(+m[2]):null; }
// เรียงแถวตามรอบ (รอบ1 ก่อน รอบ2) คงลำดับเดิมภายในรอบเดียวกัน — รองรับทั้งไฟล์เดี่ยว/ไฟล์ต่อกัน(#1/#2)
const _rows = (prep.rows||[]).map((r,i)=>({r,i}))
  .sort((a,b)=> ((a.r.round||1)-(b.r.round||1)) || (a.i-b.i))
  .map(x=>x.r);
const seq={}; let totalMin=0; const events=[];
for(const r of _rows){
  const c = prep.hasDict ? matchCause(r.cause) : { code:r.cause, thai:"", score:0, matched:false };
  const _round=(r.round||prep.round||1);
  const _seqKey=_round+"|"+c.code;
  seq[_seqKey]=(seq[_seqKey]||0)+1;
  const sm=toMin(r.stop), st=toMin(r.start);
  let dur=(sm!=null && st!=null)?(st-sm):0; if(dur<0) dur+=1440;
  totalMin+=dur;
  events.push({ date:prep.date_iso, round:_round, stop:r.stop, start:r.start,
    causeCode:c.code, causeThai:c.thai, matched:c.matched, score:c.score,
    remedy:null, technician:r.technician, operator:r.operator, seq:seq[_seqKey], durMin:dur });
}
const H=Math.floor(totalMin/60), M=totalMin%60;
return [{ json:{
  spreadsheetId: $('เริ่มเขียน1').first().json.spreadsheetId,
  sheet:prep.sheet, dictSheet:prep.dictSheet, hasDict:prep.hasDict,
  date_iso:prep.date_iso, date_disp:prep.date_disp, round:prep.round, rate:prep.rate,
  events, summary:{ text:`วันที่ ${prep.date_disp} รวมเวลาที่หายไปทั้งสิ้น`,
    totalMin, totalH:H, totalMM:M, count:events.length } } }];

// อ่านจาก $json (Merge รวม payload + valueRanges) — เขียน A-O โดย "แทรกแถวสรุปหลังข้อมูลของแต่ละรอบทันที"
// (นี่คือโค้ดที่สร้าง data/valueInputOption — คนละตัวกับ 'จับคู่ + สร้างแถว')
const p = $json;
const TARGET_ID = p.spreadsheetId;
const events = Array.isArray(p.events) ? p.events : [];

// กันเคสไม่มีแถวข้อมูลเลย: ไม่เขียน ปล่อยไฟล์ค้างที่ 2-Processiong
if (events.length === 0) {
  return [{ json: { _skip_write:true, spreadsheetId:TARGET_ID, sheet:p.sheet,
    note:"ไม่มีแถวข้อมูลให้เขียน (events ว่าง)" } }];
}

let lastRow=0;
try { const vr=p.valueRanges; const col=(vr&&vr[0]&&vr[0].values&&vr[0].values[0])?vr[0].values[0]:[]; lastRow=col.length; } catch(e){}
const firstRow=Math.max(lastRow+1,4);   // หัวตาราง 3 แถวคงที่ -> ข้อมูลเริ่มแถว 4 เป็นอย่างน้อย (กันเคส C ถูก merge แนวตั้งทำให้นับ C ขาด 1)
const pr=String(p.date_iso).split("-").map(Number); const yy=pr[0],mo=pr[1],dd=pr[2];
function timeF(t){ if(!t) return ""; const m=String(t).match(/(\d{1,2}):(\d{2})/); return m?("=TIME("+(+m[1])+","+(+m[2])+",0)"):""; }
function cell(t){ return (t==="-") ? "-" : timeF(t); }   // รองรับ "-" ทั้งช่องปิด(E)และช่องเปิด(F)
const dictSheet=p.dictSheet; const hasDict=p.hasDict;
function jF(r){ return hasDict ? ("=XLOOKUP(I"+r+",'"+dictSheet+"'!B:B,'"+dictSheet+"'!C:C,\"\")") : ""; }

// จัดกลุ่ม events ตามรอบ (ต่อเนื่อง เพราะ 'จับคู่ + สร้างแถว' เรียงตามรอบมาแล้ว)
const groups=[];
events.forEach(ev=>{ const g=groups[groups.length-1]; if(g && g.round===ev.round){ g.items.push(ev); } else { groups.push({ round:ev.round, items:[ev] }); } });

const rows=[];               // ค่าที่จะเขียน (ต่อเนื่องเริ่มที่ firstRow)
