const dataSegments=[];       // ช่วงแถวข้อมูลของแต่ละรอบ (ไว้จัดรูปแบบเทา)
const noStopRows=[];         // เลขแถว "เครื่องไม่หยุด" (ไฮไลท์แดงพิเศษ A:O ยกเว้น G,H)

groups.forEach(g=>{
