function extractRawText(j) {
  if (
    j.content &&
    j.content.parts &&
    j.content.parts[0] &&
    typeof j.content.parts[0].text === 'string'
  ) {
    return j.content.parts[0].text;
  }

  if (typeof j.text === 'string') {
    return j.text;
  }

  if (
    j.candidates &&
    j.candidates[0] &&
    j.candidates[0].content &&
    j.candidates[0].content.parts &&
    j.candidates[0].content.parts[0] &&
    typeof j.candidates[0].content.parts[0].text === 'string'
  ) {
    return j.candidates[0].content.parts[0].text;
  }

  return JSON.stringify(j);
}

function cleanJsonText(raw) {
  let clean = String(raw || '').trim();

  const fenced = clean.match(
    /```(?:json)?\s*([\s\S]*?)\s*```/i
  );

  if (fenced && fenced[1]) {
    clean = fenced[1].trim();
  }

  return clean
    .replace(/^```(?:json)?/i, '')
    .replace(/```$/i, '')
    .trim();
}

const out = [];

for (let idx = 0; idx < items.length; idx++) {
  const j = items[idx].json || {};

  // --------------------------------------------------
  // 1. File metadata
  // --------------------------------------------------
  let fileId = null;
  let fileName = null;
  let mimeType = null;

  try {
    const src = sourceFiles[idx];

    if (src && src.json) {
      fileId = src.json.id || null;
      fileName = src.json.name || null;
      mimeType = src.json.mimeType || null;
    }
  } catch (e) {}

  const extension =
    fileName && fileName.includes('.')
      ? fileName.split('.').pop().toLowerCase()
      : null;

  const file = {
    id: fileId,
    name: fileName,
    extension,
    mime_type: mimeType,
    drive_link: fileId
      ? `https://drive.google.com/file/d/${fileId}/view`
      : null
  };

  // --------------------------------------------------
  // 2. Raw OCR text
  // --------------------------------------------------
  const raw = extractRawText(j);

  let parsed = null;
  let ocrError = null;

  try {
    parsed = JSON.parse(
      cleanJsonText(raw)
    );
  } catch (e) {
    ocrError = e.message;
  }

  // --------------------------------------------------
  // 3. OCR structured object
  // --------------------------------------------------
  const ocr = parsed
    ? {
        machine_raw:
          parsed.machine_raw ?? null,

        product:
          parsed.product ?? null,

        date:
          parsed.date ?? null,

        rows:
          Array.isArray(parsed.rows)
            ? parsed.rows
            : [],

        round_summary_note:
          parsed.round_summary_note ?? null
      }
    : null;

  // --------------------------------------------------
  // 4. วันที่จาก filename YYYYMMDD
  //
  // รองรับ:
  // 015_20260703_3.JPG
  // 015_20260703_2#1.JPG
  // 015_20260703_2#2.JPG
  // 20260703 PF8-5.jpg
  // scan-20260703-PF8-5.jpg
  // --------------------------------------------------
  const dateMatch =
    String(fileName || '').match(
      /(?:^|[^0-9])(20\d{2})(\d{2})(\d{2})(?:[^0-9]|$)/
    );

  let docDateIso = null;
  let docMonthTitle = null;

  if (dateMatch) {
    const yearCE =
      parseInt(dateMatch[1], 10);

    const month =
      parseInt(dateMatch[2], 10);

    const day =
      parseInt(dateMatch[3], 10);

    if (
      month >= 1 &&
      month <= 12 &&
      day >= 1 &&
      day <= 31
    ) {
      docDateIso =
        `${yearCE}-` +
        `${String(month).padStart(2, '0')}-` +
        `${String(day).padStart(2, '0')}`;

      const yearBE =
        yearCE + 543;

      docMonthTitle =
        `รายงาน ประจำเดือน ` +
        `${THAI_MONTHS[month]} ` +
        `${yearBE}`;
    }
  }

  // --------------------------------------------------
  // 5. Lookup readiness
  // เช็กเฉพาะสิ่งที่จำเป็นจริง
  // --------------------------------------------------
  const machineRaw =
    String(
      ocr?.machine_raw || ''
    ).trim();

  const canAlarmLookup = Boolean(
    machineRaw &&
    docDateIso
  );

  // --------------------------------------------------
  // 6. Output
  // --------------------------------------------------
  out.push({
    json: {
      file,

      ocr,

      ocr_raw_text: raw,

      ocr_error: ocrError,

      _doc_date_iso:
        docDateIso,

      _doc_month_title:
        docMonthTitle,

      _can_alarm_lookup:
        canAlarmLookup,

      // debug ชั่วคราว
      _alarm_lookup_check: {
        source_file_count:
          sourceFiles.length,

        source_index:
          idx,

        has_file:
          Boolean(fileName),

        file_name:
          fileName,

        has_ocr:
          Boolean(ocr),

        machine_raw:
          machineRaw || null,

        has_filename_date:
          Boolean(docDateIso),

        doc_date_iso:
          docDateIso,

        doc_month_title:
          docMonthTitle,

        ocr_error:
          ocrError
      }
    }
  });
}

