  JSON.stringify(metadata) + "\r\n" +
  "--" + boundary + "\r\n" +
  "Content-Type: application/json; charset=UTF-8\r\n\r\n" +
  content + "\r\n" +
  "--" + boundary + "--";

return [{
  json: {
    _out_name: outName,
    _boundary: boundary,
    _upload_body: body
  }
}];

const p = { ...$json };

if (!p.ocr || !Array.isArray(p.ocr.rows)) {
  return [{ json: p }];
}

const docDateIso = String(p._doc_date_iso || '').trim();
const targetMachine = String(p.ocr.machine_raw || '').trim().toUpperCase();

function normalizeYear(y, targetYear) {
  let n = parseInt(y, 10);
  if (!Number.isFinite(n)) return null;

  if (n >= 2400) return n - 543;

  if (n < 100) {
    if (Number.isFinite(targetYear) && n === targetYear % 100) {
      return targetYear;
    }

    if (
      Number.isFinite(targetYear) &&
      n === (targetYear + 543) % 100
    ) {
      return targetYear;
    }

    return 2000 + n;
  }

  return n;
}

function parseDateIso(v) {
  const s = String(v ?? '').trim();
  const m = s.match(/(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);

  if (!m) return null;

  const targetYear = parseInt(docDateIso.slice(0, 4), 10);
  const day = parseInt(m[1], 10);
  const month = parseInt(m[2], 10);
  const year = normalizeYear(m[3], targetYear);

  if (
    !Number.isFinite(year) ||
    day < 1 || day > 31 ||
    month < 1 || month > 12
  ) {
    return null;
  }

  return (
    `${year}-` +
    `${String(month).padStart(2, '0')}-` +
    `${String(day).padStart(2, '0')}`
  );
}

function parseTimeMin(v) {
  const s = String(v ?? '').trim();
  const matches = [...s.matchAll(/(\d{1,2}):(\d{2})(?::\d{2})?/g)];

  if (!matches.length) return null;

  const m = matches[matches.length - 1];
  const h = parseInt(m[1], 10);
  const min = parseInt(m[2], 10);

  if (
    h < 0 || h > 23 ||
    min < 0 || min > 59
  ) {
    return null;
  }

  return h * 60 + min;
}

const alarmRows = Array.isArray(p._alarm_rows)
  ? p._alarm_rows
  : [];

const candidates = [];

for (let i = 0; i < alarmRows.length; i++) {
  const r = alarmRows[i] || {};

  const rowMachine = String(r['เครื่อง'] ?? '')
    .trim()
    .toUpperCase();

  if (rowMachine !== targetMachine) continue;

  const dateFromDateCol = parseDateIso(r['วันที่']);
  const dateFromDateTime = parseDateIso(r['วันที่ / เวลา']);
  const rowDateIso = dateFromDateCol || dateFromDateTime;

  if (rowDateIso !== docDateIso) continue;

  const alarmTimeMin = parseTimeMin(r['วันที่ / เวลา']);
  if (alarmTimeMin === null) continue;

  const alarmText = String(r['Alarm'] ?? '').trim();
  if (!alarmText) continue;

  candidates.push({
    time_min: alarmTimeMin,
    alarm: alarmText,
    source_index: i
  });
}

const enrichedRows = p.ocr.rows.map(row => {
  const stopMin = parseTimeMin(row.stop);

  let machineCause = null;

  if (stopMin !== null) {
    let best = null;
    let bestDiff = Infinity;

    for (const c of candidates) {
      const diff = Math.abs(stopMin - c.time_min);

      if (diff > 1) continue;

      // ถ้าระยะเท่ากัน ให้เก็บรายการแรกตามลำดับใน Sheet1
      if (diff < bestDiff) {
        best = c;
        bestDiff = diff;
      }
    }

    if (best) {
      machineCause = best.alarm;
    }
  }

  return {
    ...row,
    cause_machine: machineCause
  };
});

return [{
  json: {
    ...p,
    ocr: {
      ...p.ocr,
      rows: enrichedRows
    }
  }
}];

// ระบุชื่อ Node ที่ต้องการคำนวณ
const geminiNodes = [
  'OCR: อ่านฟอร์ม'
];

// 1. ตารางราคา (USD ต่อ 1 ล้าน Tokens)
// เงื่อนไข: เฉพาะ Text Output และ Prompt <= 200,000 Tokens 
const pricing = {
  "gemini-3.5-flash": { input: 1.5, output: 8.3 },
  // ตระกูล Gemini 3.1 (รุ่นใหม่ล่าสุด)
  "gemini-3.1-pro": { input: 2.00, output: 12.00 },
  "gemini-3.1-flash": { input: 0.50, output: 3.00 },
  "gemini-3.1-flash-lite": { input: 0.25, output: 1.50 },

  // ตระกูล Gemini 2.5
  "gemini-2.5-pro": { input: 1.25, output: 10.00 },
  "gemini-2.5-flash": { input: 0.30, output: 2.50 },
  "gemini-2.5-flash-lite": { input: 0.10, output: 0.40 },

  // Default สำรองไว้กรณีหาชื่อรุ่นไม่เจอ (อิงเรทกลางๆ ของ 2.5 Flash)
  "default": { input: 0.30, output: 2.50 } 
};

let grandTotalUsd = 0;
let totalInputAll = 0;
let totalOutputAll = 0;

// Object สำหรับเก็บสรุปยอดแยกตามโมเดล
let summaryByModel = {};

// 2. วนลูปดึงข้อมูลจากแต่ละ Node
for (const nodeName of geminiNodes) {
  try {
    const nodeData = $node[nodeName].json;
    const meta = nodeData.usageMetadata;

    // ดึงชื่อรุ่นจาก API ถ้าไม่มีให้ใช้ "default"
    let rawModelVersion = nodeData.modelVersion || "default";
    let matchedModel = "default";
    let rate = 
      ["default"];

    // ใช้การเช็กคำ (includes) เพื่อรองรับชื่อ API ที่มี suffix ต่อท้าย เช่น "gemini-2.5-pro-preview"
    for (const key in pricing) {
      if (rawModelVersion.includes(key)) {
        matchedModel = key;
        rate = pricing[key];
        break; // เจอชื่อที่ตรงกันแล้วหยุดหา
      }
    }

    if (meta) {
      const inputTokens = meta.promptTokenCount || 0;
      // รวม Candidates (คำตอบปกติ) และ Thoughts (การคิดวิเคราะห์) เข้าเป็น Output ก้อนเดียว
      const outputTokens = (meta.candidatesTokenCount || 0) + (meta.thoughtsTokenCount || 0);

      // 3. คำนวณราคา Node ปัจจุบัน
      const nodeCostUsd = (inputTokens * (rate.input / 1000000)) + (outputTokens * (rate.output / 1000000));

      grandTotalUsd += nodeCostUsd;
      totalInputAll += inputTokens;
      totalOutputAll += outputTokens;

      // บันทึกสถิติสะสมแยกตามรุ่นโมเดล
      if (!summaryByModel[matchedModel]) {
        summaryByModel[matchedModel] = {
          total_tokens: 0,
          cost_usd: 0
        };
      }
      summaryByModel[matchedModel].total_tokens += (inputTokens + outputTokens);
      summaryByModel[matchedModel].cost_usd += nodeCostUsd;
    }
  } catch (e) {
    // ข้าม Node ที่รันไม่ผ่านหรือไม่พบ
  }
}

// 4. สรุปเป็นเงินบาท (ใช้เรท 33 บาท/ดอลลาร์)
const grandTotalThb = grandTotalUsd * 33 + 1;

// จัดรูปแบบทศนิยมให้สวยงามสำหรับ Output
for (const model in summaryByModel) {
  const modelCostUsd = summaryByModel[model].cost_usd;
  summaryByModel[model].cost_thb = (modelCostUsd * 33).toFixed(4) + " บาท";
  summaryByModel[model].cost_usd = modelCostUsd.toFixed(6);
}

// 5. ส่งค่าออกไปแสดงผล
return {
  summary: {
    total_tokens_used: totalInputAll + totalOutputAll,
    tokens_breakdown: {
      input: totalInputAll,
      output_including_thoughts: totalOutputAll
    },
    cost_by_model: summaryByModel,
    grand_total: {
      usd: grandTotalUsd.toFixed(6),
      thb: grandTotalThb.toFixed(4) + " บาท"
    }
  }
};

